# The final placement has been released, but support remains obscured by the gripper.
# I will return both arms to their recorded starting joints and let the episode perform its final check.
o = get_observation()
start_home = {k: np.array(o['state'][k]).copy() for k in ['left_arm_joint_state', 'right_arm_joint_state']}
for j in range(26):
    if ended:
        break
    f = min(1.0, float(j + 1) / 16.0)
    a = {k: start_home[k] + f * (home_state[k] - start_home[k]) for k in start_home}
    a['left_ee_joint_state'] = [1]
    a['right_ee_joint_state'] = [1]
    o, reward, term, trunc, info = step(a)
    ended = term or trunc or bool(info.get('success', False))
    if ended:
        print('final', reward, term, trunc, info)
print('home errors', float(np.linalg.norm(o['state']['left_arm_joint_state'] - home_state['left_arm_joint_state'])), float(np.linalg.norm(o['state']['right_arm_joint_state'] - home_state['right_arm_joint_state'])))

